import { useEffect, useState } from "react";
import "../../css/admin/admin_dash.css";

// ======================================================
// 1. ค่าพื้นฐานสำหรับเชื่อมต่อ Backend
// ======================================================

// URL หลักของ Backend
const API_BASE_URL = "http://localhost:5001";

// แปลงรหัสสถานะการจองเป็นข้อความภาษาไทย
const STATUS_LABELS = {
  reserved: "รอดำเนินการ",
  confirmed: "ยืนยันแล้ว",
  checked_in: "เช็กอินแล้ว",
  completed: "เสร็จสิ้น",
  cancelled: "ยกเลิก",
  no_show: "ไม่มาเช็กอิน",
};

// ======================================================
// 2. ฟังก์ชันจัดรูปแบบข้อมูล
// ======================================================

// แปลงวันที่เป็นรูปแบบภาษาไทยตามเขตเวลาไทย
function formatDate(dateString) {
  if (!dateString) return "-";

  const date = new Date(
    `${String(dateString).slice(0, 10)}T00:00:00+07:00`
  );

  if (Number.isNaN(date.getTime())) return String(dateString);

  return new Intl.DateTimeFormat("th-TH", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "Asia/Bangkok",
  }).format(date);
}

// แสดงเวลาในรูปแบบ HH:mm
function formatTime(time) {
  return time ? String(time).slice(0, 5) : "-";
}

// แปลงตัวเลขให้มีเครื่องหมายคั่นหลักพันตามรูปแบบภาษาไทย
function formatNumber(value) {
  return Number(value || 0).toLocaleString("th-TH");
}

// ======================================================
// 3. คอมโพเนนต์หลักของหน้า Admin Dashboard
// ======================================================

function AdminDashboard() {
  // เก็บข้อมูลทั้งหมดที่ได้รับจาก API Dashboard
  const [dashboard, setDashboard] = useState(null);

  // ตรวจสอบสถานะการโหลดข้อมูล
  const [loading, setLoading] = useState(true);

  // เก็บข้อความแจ้งข้อผิดพลาด
  const [error, setError] = useState("");

  // ====================================================
  // 4. ฟังก์ชันโหลดข้อมูล Dashboard จาก Backend
  // ====================================================

  useEffect(() => {
    // ใช้ยกเลิกคำขอเมื่อคอมโพเนนต์ถูกถอดออกจากหน้าเว็บ
    const controller = new AbortController();

    async function loadDashboard() {
      // อ่าน Token ของผู้ใช้ที่เข้าสู่ระบบ
      const token = localStorage.getItem("token");

      // หากไม่มี Token จะไม่เรียก API
      if (!token) {
        setError("ไม่พบ Token กรุณาเข้าสู่ระบบใหม่");
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        setError("");

        // ขอข้อมูล Dashboard จาก Backend
        const response = await fetch(
          `${API_BASE_URL}/api/admin/dashboard`,
          {
            method: "GET",
            headers: {
              Authorization: `Bearer ${token}`,
              Accept: "application/json",
            },
            signal: controller.signal,
          }
        );

        // แปลงข้อมูลตอบกลับเป็น JSON
        const result = await response.json().catch(() => ({}));

        // ตรวจสอบว่าการเรียก API สำเร็จหรือไม่
        if (!response.ok || !result.success) {
          throw new Error(
            result.message || "ไม่สามารถโหลดข้อมูล Dashboard ได้"
          );
        }

        // เก็บข้อมูล Dashboard สำหรับแสดงบนหน้าเว็บ
        setDashboard(result);
      } catch (err) {
        // ไม่แสดงข้อผิดพลาดเมื่อคำขอถูกยกเลิกตามปกติ
        if (err.name !== "AbortError") {
          setError(
            err.message || "เกิดข้อผิดพลาดในการเชื่อมต่อเซิร์ฟเวอร์"
          );
        }
      } finally {
        // ปิดสถานะโหลดเมื่อคำขอยังทำงานอยู่
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      }
    }

    // เริ่มโหลดข้อมูลเมื่อเปิดหน้า Dashboard
    loadDashboard();

    // ยกเลิกคำขอเมื่อออกจากหน้า
    return () => controller.abort();
  }, []);

  // ====================================================
  // 5. เตรียมข้อมูลสำหรับแสดงผล
  // ====================================================

  // ข้อมูลสรุปจำนวนห้อง ผู้ใช้งาน และการจอง
  const summary = dashboard?.summary;

  // รายการจองของวันที่ Dashboard ส่งกลับมา
  const todayBookings = dashboard?.todayBookings || [];

  // ====================================================
  // 6. กำหนดข้อมูลการ์ดภาพรวมระบบ
  // ====================================================

  // การ์ดภาพรวม 4 ใบ ได้แก่ จำนวนห้อง ผู้ใช้งาน
  // การจองทั้งหมด และการจองวันนี้
  const cards = [
    {
      key: "rooms",
      label: "ห้องประชุมทั้งหมด",
      value: summary?.totalRooms,
      detail:
        summary == null
          ? "รอข้อมูลจากฐานข้อมูล"
          : `เปิดให้บริการ ${formatNumber(summary.availableRooms)} ห้อง`,
      icon: "▤",
      className: "rooms",
    },
    {
      key: "users",
      label: "ผู้ใช้งาน",
      value: summary?.totalUsers,
      detail: "นักศึกษาและอาจารย์",
      icon: "♙",
      className: "users",
    },
    {
      key: "bookings",
      label: "การจองทั้งหมด",
      value: summary?.totalBookings,
      detail: "รายการในฐานข้อมูล",
      icon: "▣",
      className: "bookings",
    },
    {
      key: "today",
      label: "การจองวันนี้",
      value: summary?.todayBookingsCount,
      detail: "รายการตามวันที่ประเทศไทย",
      icon: "◷",
      className: "today",
    },
  ];

  // ====================================================
  // 7. ส่วนแสดงผลหน้า Dashboard
  // ====================================================

  return (
    <div className="admin-dashboard">

      {/* ส่วนหัวหน้า Dashboard และวันที่ของข้อมูล */}
      <section className="admin-dashboard-intro">
        <div>
          <p className="admin-eyebrow">SYSTEM OVERVIEW</p>

          <h2>ภาพรวมระบบ</h2>

          <p className="admin-dashboard-description">
            ตรวจสอบข้อมูลห้องประชุม ผู้ใช้งาน และการจองจากฐานข้อมูล Booking CSTU
          </p>
        </div>

        {/* แสดงวันที่อ้างอิงจาก Backend */}
        <div className="admin-dashboard-date">
          <span>วันที่ข้อมูล</span>

          <strong>
            {dashboard ? formatDate(dashboard.date) : "กำลังโหลด..."}
          </strong>
        </div>
      </section>

      {/* ส่วนแสดงข้อความเมื่อโหลดข้อมูลไม่สำเร็จ */}
      {error && (
        <section className="admin-dashboard-error" role="alert">
          <strong>โหลดข้อมูลไม่สำเร็จ</strong>

          <p>{error}</p>

          {/* รีโหลดหน้าเพื่อทดลองเรียก API อีกครั้ง */}
          <button
            type="button"
            onClick={() => window.location.reload()}
          >
            ลองอีกครั้ง
          </button>
        </section>
      )}

      {/* ==================================================
          8. การ์ดภาพรวมระบบ
          แสดงจำนวนห้อง ผู้ใช้งาน การจองทั้งหมด และการจองวันนี้
         ================================================== */}
      <section
        className="admin-dashboard-cards"
        aria-label="สรุปข้อมูลระบบ"
      >
        {cards.map((card) => (
          <article
            className={`admin-stat-card ${card.className}`}
            key={card.key}
          >
            {/* ชื่อและไอคอนของการ์ด */}
            <div className="admin-stat-card-top">
              <span className="admin-stat-label">
                {card.label}
              </span>

              <span className="admin-stat-icon" aria-hidden="true">
                {card.icon}
              </span>
            </div>

            {/* ตัวเลขสรุปของการ์ด */}
            <div className="admin-stat-value">
              {loading || error
                ? "—"
                : formatNumber(card.value)}
            </div>

            {/* คำอธิบายใต้ตัวเลข */}
            <p className="admin-stat-detail">
              {loading ? "กำลังโหลดข้อมูล..." : card.detail}
            </p>
          </article>
        ))}
      </section>

      {/* ==================================================
          9. ตารางรายการจองวันนี้
          ตัดส่วนสถิติแยกตามสถานะออกแล้ว
         ================================================== */}
      <section className="admin-dashboard-panel admin-today-panel">

        {/* หัวข้อและจำนวนรายการจองของวันนี้ */}
        <div className="admin-panel-heading">
          <div>
            <h2>รายการจองวันนี้</h2>

            <p>
              {dashboard
                ? formatDate(dashboard.date)
                : "รายการจองจากฐานข้อมูล"}
            </p>
          </div>

          <span className="admin-today-count">
            {loading
              ? "กำลังโหลด..."
              : `${formatNumber(todayBookings.length)} รายการ`}
          </span>
        </div>

        {/* แสดงข้อความระหว่างโหลดข้อมูล */}
        {loading ? (
          <div className="admin-dashboard-message">
            กำลังโหลดรายการจอง...
          </div>
        ) : error ? (
          /* แสดงข้อความเมื่อโหลดรายการจองไม่สำเร็จ */
          <div className="admin-dashboard-message">
            ไม่สามารถโหลดรายการจองได้
          </div>
        ) : todayBookings.length === 0 ? (
          /* แสดงข้อความเมื่อไม่มีรายการจองในวันนี้ */
          <div className="admin-dashboard-empty">
            <span className="admin-empty-icon" aria-hidden="true">
              ▦
            </span>

            <strong>ไม่มีรายการจองวันนี้</strong>

            <p>ไม่พบรายการจองในวันที่แสดงอยู่</p>
          </div>
        ) : (
          /* ตารางข้อมูลการจองเมื่อมีรายการ */
          <div className="admin-table-scroll">
            <table className="admin-dashboard-table">
              <thead>
                <tr>
                  <th>รหัสจอง</th>
                  <th>ห้องประชุม</th>
                  <th>ผู้จอง</th>
                  <th>เวลา</th>
                  <th>สถานะ</th>
                </tr>
              </thead>

              <tbody>
                {/* วนแสดงรายการจองแต่ละรายการ */}
                {todayBookings.map((booking) => (
                  <tr key={booking.booking_id}>

                    {/* รหัสการจอง */}
                    <td className="admin-booking-id">
                      #{booking.booking_id}
                    </td>

                    {/* รหัสห้องและชื่อห้อง */}
                    <td>
                      <strong>{booking.room_code}</strong>

                      <span className="admin-table-secondary">
                        {booking.room_name}
                      </span>
                    </td>

                    {/* ชื่อผู้จอง */}
                    <td>{booking.user_name || "-"}</td>

                    {/* เวลาเริ่มต้นและสิ้นสุดการจอง */}
                    <td className="admin-booking-time">
                      {formatTime(booking.start_time)}–
                      {formatTime(booking.end_time)}
                    </td>

                    {/* สถานะการจองของรายการนั้น */}
                    <td>
                      <span
                        className={`admin-booking-status status-${booking.status}`}
                      >
                        {STATUS_LABELS[booking.status] || booking.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  );
}

export default AdminDashboard;
